// Validate validates c.
func (c EtcdConf) Validate() error {
	if len(c.Hosts) == 0 {
		return errors.New("empty etcd hosts")
	} else if len(c.Key) == 0 {
		return errors.New("empty etcd key")
	} else if (len(c.User) > 0 && len(c.Password) == 0) || (len(c.User) == 0 && len(c.Password) > 0) {
		return errors.New("etcd user and password must be set together")
	} else {
		return nil
	}
}

