arguments.newString:
func getClusterKey(endpoints []string, user, password string) string {
	sort.Strings(endpoints)
	key := strings.Join(endpoints, endpointsSeparator)
	if user != "" {
		key = key + endpointsSeparator + user
	}
	if password != "" {
		key = key + endpointsSeparator + password
	}
	return key
}

